using System.Collections;
using System.Collections.Generic;
using UnityEngine;
public sealed partial class TrainingGame
{
 readonly GreaseFields grease=new GreaseFields();
    bool greaseResolving;
 sealed class GreaseEntry {public int Actor;public GreaseField Field;public long MoveEvent;public int MoveStep;}
 readonly Queue<GreaseEntry> greaseEntries=new Queue<GreaseEntry>();
 void InitializeGrease(){map.MovementObserved=ObserveGreaseMovement;map.SwimmingTerrain=(cell,spaces)=>map.WaterCells(cell,spaces)==spaces*spaces;}
 bool FullDifficultTerrain(int x,int y,int spaces){for(int j=0;j<spaces;j++)for(int i=0;i<spaces;i++)if(!entangle.FullFootprint(x+i,y+j,1,worldRounds)&&!grease.Cell(x+i,y+j,worldRounds,map.Scene)&&!spikeGrowth.Cell(x+i,y+j,worldRounds)&&!web.Cell(x+i,y+j,worldRounds)&&!iceStorm.Cell(x+i,y+j,worldRounds,map.Scene)&&!SleetLandCell(x+i,y+j))return false;return spaces>0;}
 void ObserveGreaseMovement(int actor,Vector2Int from,Vector2Int to,int oldSpaces,int spaces,bool landing)
 {
  BondBonus(0);RefreshFireShield();RefreshFlameBlade();RefreshShiningSmite();RefreshWitchBolt();terrainMovementEvent++;RefreshFaerieFire();RefreshDancingLights();RefreshLightSpell();ObserveSpikeMovement(actor,from,to,spaces,landing);ObserveWebMovement(actor,from,to,oldSpaces,spaces,landing);ObserveDaggersMovement(actor,from,to,oldSpaces,spaces,landing);ObservePackMovement(actor,from,to,oldSpaces,spaces,landing);ObserveSleetMovement(actor,from,to,oldSpaces,spaces,landing);ObserveGuardianMovement(actor,from,to,oldSpaces,spaces,landing);RefreshGustClouds();
  if(!map.Locked||!grease.Any(worldRounds))return;var path=landing?new List<Vector2Int>{to}:BattleMap.MovementAnchors(from,to);var previous=from;int previousSpaces=oldSpaces,step=0;
  foreach(var cell in path){var field=grease.Current(cell.x,cell.y,spaces,worldRounds,map.Scene);if(field!=null&&!field.Intersects(previous.x,previous.y,previousSpaces))greaseEntries.Enqueue(new GreaseEntry{Actor=actor,Field=field,MoveEvent=terrainMovementEvent,MoveStep=step});previous=cell;previousSpaces=spaces;step++;}
 }
 GreaseField ActorGrease(int actor){if((actor==0||actor==-1)&&(map.IsContained(actor==0)||map.IsCarried(actor==0)))return null;if(actor==0)return grease.Current(map.Player.x,map.Player.y,map.PlayerSpaces,worldRounds,map.SceneOf(actor));if(actor==-1)return grease.Current(map.Monster.x,map.Monster.y,map.MonsterSpaces,worldRounds,map.SceneOf(actor));if(actor==BattleMap.RescueId&&map.RescuePosition.HasValue)return grease.Current(map.RescuePosition.Value.x,map.RescuePosition.Value.y,map.RescueSpaces,worldRounds,map.SceneOf(actor));var unit=FindSummon(actor);return unit==null?null:grease.Current(unit.X,unit.Y,unit.Spaces,worldRounds,map.SceneOf(actor));}
 int GreaseLand(Vector2Int anchor){int mask=0;for(int y=0;y<2;y++)for(int x=0;x<2;x++){var cell=anchor+new Vector2Int(x,y);if(map.Inside(cell,1)&&!map.IsWater(cell))mask|=1<<(y*2+x);}return mask;}
 string GreaseError(){Vector2Int cell;if(!VisionPoint(out cell))return "油脂区域左上格须位于地图内。";return GreaseDistance(cell)>60?"区域中心超出60尺。":grease.CanAdd(worldRounds)?"":"时间或区域编号超出范围。";}
 int GreaseDistance(Vector2Int anchor){double best=double.MaxValue;for(int y=0;y<map.PlayerSpaces;y++)for(int x=0;x<map.PlayerSpaces;x++){double dx=anchor.x+.5-map.Player.x-x,dy=anchor.y+.5-map.Player.y-y;best=System.Math.Min(best,System.Math.Sqrt(dx*dx+dy*dy)*5);}return Mathf.RoundToInt((float)best);}
 void DrawGreaseChoices(){GUILayout.Label("10尺方形（2×2格），输入左上格列／行；中心位于区域中央格线交点。仅陆地生效，不易燃，非专注1分钟。",small);visionColumn=IntegerField(visionColumn,false);visionRow=IntegerField(visionRow,false);}
 void DrawGreaseArea(Rect board){Vector2Int anchor=Vector2Int.zero;bool preview=panel=="spells"&&selectedSpellName=="Grease"&&VisionPoint(out anchor);if(!preview&&!grease.Any(worldRounds))return;for(int y=0;y<map.Size;y++)for(int x=0;x<map.Size;x++){var cell=new Vector2Int(x,y);if(grease.Cell(x,y,worldRounds,map.Scene))Fill(CellRect(board,cell),new Color(.65f,.48f,.05f,.4f));if(preview&&x>=anchor.x&&x<anchor.x+2&&y>=anchor.y&&y<anchor.y+2&&!map.IsWater(cell))Fill(CellRect(board,cell),new Color(.9f,.7f,.15f,.4f));}}
 IEnumerator ResolveGrease(Vector2Int anchor,int caster){var added=grease.Add(anchor.x,anchor.y,GreaseLand(anchor),8L+classes.ProficiencyBonus+AcidSplash.Modifier(attributes[SpellAbilityIndex(caster)]),worldRounds,map.Scene);var actors=new List<int>{-1,0};foreach(var unit in map.SceneSummons)if(unit.Alive)actors.Add(unit.Id);if(map.RescuePosition.HasValue)actors.Add(BattleMap.RescueId);foreach(int actor in actors)if(ActorGrease(actor)==added)yield return ResolveGreaseSave(actor,added,"油脂出现");history.Insert(0,"油腻术：仅陆地形成非易燃油脂，非专注1分钟；出现、进入和回合末敏捷豁免失败倒地。");}
 IEnumerator ResolveGreaseSave(int actor,GreaseField field,string reason)
 {
  if(field==null||!field.Active(worldRounds))yield break;
  bool player=actor==0,monsterActor=actor==-1,rescue=actor==BattleMap.RescueId;var unit=actor>0?FindSummon(actor):null;
  if(player&&combat.PlayerDead||monsterActor&&combat.Hp==0||rescue&&(!map.RescuePosition.HasValue||rescueCarrier.Dead)||!player&&!monsterActor&&!rescue&&(unit==null||!unit.Alive))yield break;
  int value,modifier;int[] shown;bool automatic=false;string name=player?"玩家":monsterActor?"木桩":rescue?"救援者":unit.Name;
  if(player||monsterActor){var roll=RollArmorSave(player,1);value=roll.Value;shown=roll.Dice;modifier=player?PlayerSavingThrowModifier(1):MonsterSavingThrowModifier(1);automatic=player?combat.PlayerHp==0||combat.PlayerParalyzed:combat.MonsterParalyzed||combat.MonsterSleepStage==2;var adjustment=new SaveAdjustment();yield return ApplySaveAdjustments(player,automatic,adjustment,1);modifier+=adjustment.Value;}
  else if(rescue){var rescueRoll=RollRescueSave(1);value=rescueRoll.Value;shown=rescueRoll.Dice;modifier=BondBonus(actor)+rescueCarrier.DexteritySaveModifier;automatic=rescueCarrier.Hp==0||rescueCarrier.Dead;}
  else {automatic=unit.SleepStage==2;bool advantage=unit.Dodging&&unit.EffectiveSpeed>0,disadvantage=unit.Restrained;int first=Random.Range(1,21),second=advantage!=disadvantage?Random.Range(1,21):0;value=second==0?first:advantage?Mathf.Max(first,second):Mathf.Min(first,second);shown=second==0?new[]{first}:new[]{first,second};modifier=BondBonus(actor)+SummonSaveModifier(unit,1)+unit.Breathing.D20Penalty;}
  if(!automatic){string savedPanel=panel;if(rescue)panel="";try{yield return PresentRoll(20,shown,reason+" · "+name+"敏捷豁免："+value+" + "+modifier+" / DC "+field.Dc);}finally{if(rescue)panel=savedPanel;}}
  if(automatic||(long)value+modifier<field.Dc){if(player)combat.PlayerProne=true;else if(monsterActor)combat.MonsterProne=true;else if(rescue)rescueCarrier.Prone=true;else unit.Prone=true;SyncTimedBuffs();history.Insert(0,name+"油腻术豁免失败，倒地。");}else history.Insert(0,name+"通过油腻术敏捷豁免。");
 }
 IEnumerator DrainGreaseEntries(){if(greaseResolving){while(greaseResolving)yield return null;yield break;}bool busy=rolling;rolling=true;greaseResolving=true;try{while(PendingTerrainCount>0){if(packEntries.Count>0){yield return ChoosePackEntryOrder();if(packFirst){yield return ResolvePackEntry(packEntries.Dequeue());continue;}if(PendingTerrainCount==0)continue;}if(startStatuses.Count>0){yield return ChooseStartStatusOrder();if(startStatusFirst){yield return ResolveStartStatus();continue;}}if(auraStarts.Count>0){yield return ChooseAuraVitalityOrder();if(auraFirst&&auraStarts.Count>0){yield return ResolveAuraVitalityHealing(auraStarts.Dequeue());continue;}if(PendingTerrainCount==0)continue;}if(heroismEntries.Count>0){yield return ChooseHeroismStartOrder();if(heroismFirst&&heroismEntries.Count>0){yield return ResolveHeroismStart(heroismEntries.Dequeue());continue;}if(PendingTerrainCount==0)continue;}yield return ChooseDaggersEntryOrder();if(terrainDaggersFirst){yield return ResolveDaggersEntry(daggerEntries.Dequeue());continue;}if(greaseEntries.Count>0){var entry=greaseEntries.Dequeue();yield return ResolveGreaseSave(entry.Actor,entry.Field,"进入油脂");}else if(spikeEntries.Count>0)yield return ResolveSpikeEntry(spikeEntries.Dequeue());else if(webEntries.Count>0)yield return ResolveWebEntry(webEntries.Dequeue());else yield return ResolveDaggersEntry(daggerEntries.Dequeue());}}finally{rolling=busy;greaseResolving=false;}}
 bool GreasePathNeeded(bool player,Vector2Int target){if(map.CreaturePathNeedsSteps(player?0:-1,player?map.Player:map.Monster,target,player?map.PlayerSpaces:map.MonsterSpaces))return true;if(DaggersPathNeeded(player?map.Player:map.Monster,target,player?map.PlayerSpaces:map.MonsterSpaces)||SpikePathNeeded(player,target)||WebPathNeeded(player?map.Player:map.Monster,target,player?map.PlayerSpaces:map.MonsterSpaces))return true;if(!grease.Any(worldRounds))return false;var from=player?map.Player:map.Monster;int spaces=player?map.PlayerSpaces:map.MonsterSpaces;foreach(var cell in BattleMap.MovementAnchors(from,target)){var field=grease.Current(cell.x,cell.y,spaces,worldRounds,map.Scene);if(field!=null&&!field.Intersects(from.x,from.y,spaces))return true;from=cell;}return false;}
 IEnumerator MoveThroughGrease(bool player,Vector2Int target,bool tactical,bool preserveBusy)
 {
  if(!(player?map.CanMoveTo(target,tactical):map.CanMoveMonsterTo(target)))yield break;
  var origin=player?map.Player:map.Monster;int spaces=player?map.PlayerSpaces:map.MonsterSpaces;bool crawling=player?combat.PlayerProne:combat.MonsterProne;var meter=map.RouteMeter(origin,target,crawling);var previousCell=origin;
  bool aftermath= combat.Aftermath;rolling=true;try{foreach(var cell in BattleMap.MovementAnchors(origin,target)){
   int previousTravel=meter.Travelled;int cost=map.RouteStepCost(meter,previousCell,cell,spaces,player?map.PlayerSwimmingSpeed:map.MonsterSwimmingSpeed,player?0:-1);previousCell=cell;if(cost<1)continue;
   bool legal=map.WithCreatureTransitStep(player?0:-1,()=>map.WithMovementCost(cell,cost,()=>player?map.CanMoveTo(cell,tactical):map.CanMoveMonsterTo(cell)));if(!legal)break;
   bool wasProne=player?combat.PlayerProne:combat.MonsterProne;
   yield return ResolveMovement(player,cell,tactical,true,false,true,cost,spaces,meter.Travelled-previousTravel);if((player?map.Player:map.Monster)!=cell)break;
   if((player?combat.PlayerProne:combat.MonsterProne)&&!wasProne){if(player){movementMessage="地形使玩家倒地，停在触发格；剩余路程未扣费。";break;}int stand=combat.MonsterSpeed/2;if(combat.MonsterSpeed<=0||map.MonsterMovementRemaining<stand)break;map.SpendMonsterMovement(stand);combat.MonsterProne=false;SyncTimedBuffs();history.Insert(0,"木桩花费"+stand+"尺移动力起身，继续追击。");}
   if(!aftermath&&combat.BattleFinished||player&&(combat.PlayerDead||combat.PlayerHp<=0||combat.PlayerParalyzed)||!player&&!(CommandMoving(-1)?CommandCanMove(-1):combat.MonsterCanMove)||(player?map.PlayerSpaces:map.MonsterSpaces)!=spaces)break;
  }}finally{ObserveForcedSharedStop(player?0:-1);if(!preserveBusy)rolling=false;}
 }
}
